const $=id=>document.getElementById(id),video=$('camera'),canvas=$('overlay'),ctx=canvas.getContext('2d'),stage=$('stage'),tracker=createMeleeTracker(),audio=createSpellAudio();
const captureCanvas=document.createElement('canvas'),captureContext=captureCanvas.getContext('2d');
const faceDemo={id:'target',x:.42,y:.28,width:.16,height:.18};let health=70,hits=0,stream,worker,workerReady=false,busy=false,seq=0,epoch=0,captureTimer,workerTimer,initTimer,drawFrame=0,simTimer,feedbackTimer,lastHand=null,displayHand=null,faces=[],landmarks=[],lastResult=0,metrics=0,result={phase:'ready',cooldownRemaining:0},demo=true,hitAt=-Infinity;
